<?php
require __DIR__ . '/config/config.php';
$slug = trim((string)($_GET['slug'] ?? ''));
$st = db()->prepare('SELECT * FROM cars WHERE is_active=1 AND (slug=? OR CAST(id AS CHAR)=?) LIMIT 1');
$st->execute([$slug,$slug]); $car=$st->fetch();
if (!$car) { http_response_code(404); $pageTitle='Kendaraan tidak ditemukan'; require __DIR__.'/includes/header.php'; echo '<main class="page-content"><div class="container"><h1>Kendaraan tidak ditemukan</h1><a href="'.e(url()).'#mobil">Kembali ke katalog</a></div></main>'; require __DIR__.'/includes/footer.php'; exit; }
$st=db()->prepare('SELECT * FROM car_variants WHERE car_id=? AND is_active=1 ORDER BY sort_order,name');$st->execute([$car['id']]);$variants=$st->fetchAll();
$selected=$variants[0]??null; $wanted=(int)($_GET['variant']??0);foreach($variants as $v)if($wanted && (int)$v['id']===$wanted)$selected=$v;
$specs=[];$colors=[];if($selected){$st=db()->prepare('SELECT * FROM car_specifications WHERE variant_id=? ORDER BY spec_group,sort_order,id');$st->execute([$selected['id']]);$specs=$st->fetchAll();$st=db()->prepare('SELECT * FROM car_colors WHERE variant_id=? AND is_active=1 ORDER BY sort_order,id');$st->execute([$selected['id']]);$colors=$st->fetchAll();}
$pageTitle=$car['name'].' | '.SITE_NAME;$description=(string)($car['description']??'Detail kendaraan Daihatsu '.$car['name']);require __DIR__.'/includes/header.php';
$mainImage=$colors[0]['image_url']??($car['image_url']??'');
?>
<main class="page-content"><div class="container vehicle-detail">
<p class="eyebrow"><a href="<?=e(url())?>#mobil">Mobil Daihatsu</a> / <?=e($car['name'])?></p>
<div class="vehicle-hero"><div class="vehicle-image-wrap"><?php if($mainImage):?><img id="vehicleMainImage" class="vehicle-main-image" src="<?=e($mainImage)?>" alt="<?=e($car['name'])?>"><?php else:?><div class="vehicle-image-placeholder">Foto kendaraan belum tersedia</div><?php endif;?></div>
<div class="vehicle-summary"><span class="tag"><?=e($car['category'])?></span><h1><?=e($car['name'])?></h1><?php if($car['description']):?><p><?=nl2br(e($car['description']))?></p><?php endif;?>
<?php if($variants):?><label for="variantSelect">Pilih tipe kendaraan</label><select id="variantSelect" class="vehicle-select"><?php foreach($variants as $v):?><option value="<?=(int)$v['id']?>" <?=((int)$v['id']===(int)$selected['id'])?'selected':''?>><?=e($v['name'])?><?=$v['transmission']?' · '.e($v['transmission']):''?></option><?php endforeach;?></select><div class="vehicle-price" id="variantPrice"><?=$selected['price']!==null?'Rp '.number_format((float)$selected['price'],0,',','.'): 'Hubungi cabang untuk informasi harga'?></div><?php endif;?>
<a class="btn btn-red" href="<?=e($car['contact_url']?:url().'#cabang')?>">Tanya kendaraan ini</a></div></div>
<section class="vehicle-section"><h2>Pilih warna</h2><p class="muted">Pilih warna untuk melihat foto kendaraan yang sesuai.</p><div class="vehicle-colors" id="vehicleColors"><?php foreach($colors as $i=>$color):?><button type="button" class="vehicle-color <?=$i===0?'active':''?>" data-image="<?=e($color['image_url'])?>" data-color="<?=e($color['name'])?>" aria-pressed="<?=$i===0?'true':'false'?>"><span class="color-swatch" style="background-color:<?=e($color['color_code']?:'#ddd')?>"></span><span><?=e($color['name'])?></span></button><?php endforeach;?><?php if(!$colors):?><p>Warna belum ditambahkan untuk tipe ini.</p><?php endif;?></div></section>
<section class="vehicle-section" id="vehicleSpecs"><h2>Spesifikasi kendaraan</h2><?php if($specs):$groups=[];foreach($specs as $sp)$groups[$sp['spec_group']][]=$sp;?><div class="spec-groups"><?php foreach($groups as $group=>$items):?><div class="spec-group"><h3><?=e($group)?></h3><dl><?php foreach($items as $item):?><div class="spec-row"><dt><?=e($item['spec_name'])?></dt><dd><?=nl2br(e($item['spec_value']))?></dd></div><?php endforeach;?></dl></div><?php endforeach;?></div><?php else:?><p>Spesifikasi belum ditambahkan untuk tipe ini.</p><?php endif;?></section>
</div></main>
<script>
const vehicleData=<?=json_encode(array_map(function($v){$s=db()->prepare('SELECT * FROM car_specifications WHERE variant_id=? ORDER BY spec_group,sort_order,id');$s->execute([$v['id']]);$specs=$s->fetchAll();$s=db()->prepare('SELECT * FROM car_colors WHERE variant_id=? AND is_active=1 ORDER BY sort_order,id');$s->execute([$v['id']]);return ['id'=>(int)$v['id'],'price'=>$v['price']===null?null:(float)$v['price'],'colors'=>$s->fetchAll(),'specs'=>$specs];},$variants),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>;
const variantSelect=document.getElementById('variantSelect'), colorBox=document.getElementById('vehicleColors'), mainImage=document.getElementById('vehicleMainImage'), priceBox=document.getElementById('variantPrice');
function escapeHtml(value){return String(value??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[c]));}
function renderColors(id){const v=vehicleData.find(x=>x.id===Number(id));if(!v||!colorBox)return;colorBox.innerHTML='';const specsBox=document.getElementById('vehicleSpecs');if(specsBox){let html='<h2>Spesifikasi kendaraan</h2>';if(!v.specs.length){html+='<p>Spesifikasi belum ditambahkan untuk tipe ini.</p>';}else{const groups={};v.specs.forEach(s=>{(groups[s.spec_group]??=[]).push(s)});html+='<div class="spec-groups">';Object.keys(groups).forEach(g=>{html+='<div class="spec-group"><h3>'+escapeHtml(g)+'</h3><dl>';groups[g].forEach(s=>{html+='<div class="spec-row"><dt>'+escapeHtml(s.spec_name)+'</dt><dd>'+escapeHtml(s.spec_value).replace(/\n/g,'<br>')+'</dd></div>'});html+='</dl></div>'});html+='</div>';}specsBox.innerHTML=html;}if(priceBox)priceBox.textContent=v.price===null?'Hubungi cabang untuk informasi harga':'Rp '+new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(v.price);if(!v.colors.length){colorBox.textContent='Warna belum ditambahkan untuk tipe ini.';return;}v.colors.forEach((c,i)=>{const b=document.createElement('button');b.type='button';b.className='vehicle-color'+(i===0?' active':'');b.setAttribute('aria-pressed',i===0?'true':'false');b.dataset.image=c.image_url||'';b.dataset.color=c.name||'';const sw=document.createElement('span');sw.className='color-swatch';sw.style.backgroundColor=c.color_code||'#ddd';const label=document.createElement('span');label.textContent=c.name;b.append(sw,label);colorBox.appendChild(b);});if(mainImage&&v.colors[0].image_url){mainImage.src=v.colors[0].image_url;mainImage.style.display='';mainImage.alt=<?=json_encode($car['name'])?>+' - '+v.colors[0].name;}}
if(colorBox)colorBox.addEventListener('click',e=>{const b=e.target.closest('.vehicle-color');if(!b)return;colorBox.querySelectorAll('button').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});b.classList.add('active');b.setAttribute('aria-pressed','true');if(mainImage&&b.dataset.image){mainImage.src=b.dataset.image;mainImage.alt=<?=json_encode($car['name'])?>+' - '+b.dataset.color;}});
if(variantSelect)variantSelect.addEventListener('change',()=>{const u=new URL(location.href);u.searchParams.set('variant',variantSelect.value);history.replaceState({},'',u);renderColors(variantSelect.value)});
</script>
<?php require __DIR__.'/includes/footer.php'; ?>
